SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0770000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 77, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "77", "printedPageNumber": 77, "pdfPageNumber": 460, "sequenceIndex": 67, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0770100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—VII", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0770200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—VIII", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0770000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (b)—Stories of the Pious", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 77"}, {"id": "f0770100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "She served me for some time, but I was in the dark about her state of affairs. She had a corner in the house reserved for her salaat. After finishing her job, she would go there and offer her salaat. One night, I noticed her performing salaat and then supplicating before Allah. While making her supplication, she said, ''By the love Thou hast for me, do such and such a thing for me.'' I shouted out to her, ''O woman, say by the love that I have for Thee.'' She retorted, ''My Master, if He had not loved me, He would not have made me stand for salaat and deprive you thereof.'' Next morning I sent for her and said to her, ''You are a misfit in your present job. You are exclusively meant for Allah''s service.'' I then gave her some gifts and set her free.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 77"}, {"id": "f0770200-0000-4000-8000-000000000001", "structuralNodeId": "b0770100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—VII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 77"}, {"id": "f0770300-0000-4000-8000-000000000001", "structuralNodeId": "b0770100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Sirri Saqti (Rahmatullah alaih) writes about another woman: \"When she stood up for Tahajjud she would say, ''O Allah! Satan is but Thy creation. Thou hast full power over him. He sees me and I cannot see him. Thou seest him and hast control over all his actions, while he has no control over Thee; O, Allah! repel the evil that he wishes to do me. Requit the wrong he may do to deceive me. I seek Thy refuge from his evil designs and with Thy help I cast him away.'' Thereafter she would cry bitterly. And as a result thereof she lost the sight of one eye. People admonished her to stop excessive weeping, lest she should lose her other eye as well. She replied, \"If it is destined to be an eye of Paradise, Allah will grant me better than this; but if it be that of Hell, then the sooner it is lost the better.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 77"}, {"id": "f0770400-0000-4000-8000-000000000001", "structuralNodeId": "b0770200-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—VIII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 77"}, {"id": "f0770500-0000-4000-8000-000000000001", "structuralNodeId": "b0770200-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Shaikh Abu Abdullah Jilaa says: \"One day my mother asked my father to fetch some fish from the market. My father left for the market and I also accompanied him. The fish was bought and we needed a porter to carry it for us. We engaged a boy who was standing there and who had offered to do the job for us. He put the load on his head and followed us. While we were on our way, we happened to hear the Azaan. The boy abruptly spoke, ''Allah''s summoner has summoned me; I have to take my wudhu too. I shall now carry the fish after salaat. If you like you may wait, otherwise here it is.'' Saying this he put the load down and left for the musjid. My father thought when the", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 77"}]}'::jsonb);